    return `<div class="dialog-scrim" data-start-scrim><div class="device-dialog start-dialog" role="dialog" aria-modal="true"><div class="dialog-head"><div><span class="eyebrow">Kalıcı yetiştirme kaydı</span><h2>Yeni yetiştirmeyi başlat</h2></div><ha-icon-button data-close-start><ha-icon icon="mdi:close"></ha-icon></ha-icon-button></div><div class="dialog-body"><div class="journal-safety"><ha-icon icon="mdi:shield-check-outline"></ha-icon><span><b>Günlük iki storage belgesine yazılır</b><small>Önceki yetiştirmeler arşivde kalır. İstediğiniz zaman checksummed JSON yedeği indirebilirsiniz.</small></span></div><div class="start-grid"><label><span>Yetiştirme adı</span><input data-start-name maxlength="80" placeholder="Örn. 2026 Sonbahar RDWC"></label><label><span>Başlangıç tarihi</span><input data-start-date type="date" max="${today}" value="${today}"></label><label><span>Bitki türü *</span><input data-start-species maxlength="96" placeholder="Örn. Domates"></label><label><span>Cultivar / çeşit</span><input data-start-cultivar maxlength="96" placeholder="Çeşit adı"></label><label><span>Kaynak</span><input data-start-source maxlength="160" placeholder="Tohum, fide veya tedarikçi"></label><label><span>Bitki sayısı</span><input data-start-count type="number" min="1" max="10000" value="1"></label><label><span>Yetiştirme yöntemi</span><select data-start-method><option value="RDWC">RDWC</option><option value="DWC">DWC</option><option value="NFT">NFT</option><option value="Ebb and Flow">Ebb and Flow</option><option value="Drip">Damla</option><option value="Other">Diğer</option></select></label><label><span>Rezervuar hacmi</span><div><input data-start-reservoir type="number" min="0" step="0.1" placeholder="0"><small>L</small></div></label><label><span>Toplam sistem hacmi</span><div><input data-start-system-volume type="number" min="0" step="0.1" placeholder="0"><small>L</small></div></label><label><span>Fotoperiyot kaynağı</span><select data-start-photoperiod><option value="profile">Aşama profilleri</option><option value="manual">Manuel program</option></select></label><label><span>Besin programı</span><input data-start-nutrients maxlength="160" placeholder="Program veya seri adı"></label></div><label class="journal-note"><span>Başlangıç notları</span><textarea data-start-notes maxlength="4000" placeholder="Kurulum, hedefler ve başlangıç koşulları"></textarea></label><div class="readiness-line"><ha-icon icon="mdi:clipboard-text-outline"></ha-icon><span>Tavsiye edilen izleme seti: ${readiness.ready_count}/${readiness.required_count}. Eksikler başlangıcı engellemez; sistem izleme modunda kalır.</span></div><div class="device-message" data-start-message>${this._html(this._journalNotice)}</div></div><div class="dialog-actions"><ha-button data-close-start appearance="plain">Vazgeç</ha-button><ha-button data-confirm-start appearance="filled">Kaydı oluştur ve başlat</ha-button></div></div></div>`;
