    const groups=[...new Set(fluids.map((fluid)=>fluid.brand||"Marka seçilmedi"))].map((brand)=>({brand,fluids:fluids.filter((fluid)=>(fluid.brand||"Marka seçilmedi")===brand)}));
    const phaseLabels={growth:"Gelişim",bloom:"Çiçeklenme",all:"Tüm dönemler"};
    const pumpChannels=(this._hardwareDraft?.device_assignments||[]).filter((item)=>item.driver==="waveshare_motor_hat").flatMap((item)=>(item.channels||[]).map((channel)=>({...channel,address:item.address})));
    const requiredPumps=["ph_up","ph_down"].map((fluidId)=>pumpChannels.find((channel)=>channel.fluid_id===fluidId&&channel.calibration));
    const dosingReady=requiredPumps.every(Boolean);
