  _dosingView(){
    const fluids=this._hardwareDraft?.dosing_fluids||[],hats=(this._hardwareDraft?.device_assignments||[]).filter((item)=>item.driver==="waveshare_motor_hat");
    const channels=hats.flatMap((hat,hatIndex)=>{const address=`0x${Number(hat.address).toString(16).padStart(2,"0")}`;const configuredName=(hat.name||"").trim();const generic=!configuredName||configuredName.toUpperCase()==="PCA9685"||configuredName.toLowerCase().includes("waveshare_motor_hat");const cardName=generic?`Motor HAT ${hatIndex+1}`:configuredName;return (hat.channels||[]).map((channel)=>({...channel,address:hat.address,address_label:address,card_name:cardName}));});
    const rows=channels.map((channel)=>{const cal=channel.calibration;return `<div class="dosing-map-row"><span><ha-icon icon="mdi:pump"></ha-icon><span><b>${channel.card_name} · ${channel.address_label} · Motor ${channel.id}</b><small>${channel.pump?.brand||"Pompa"} · ${channel.pump?.model||"Model belirtilmedi"}</small></span></span><span class="dosing-flow"><small>Kalibrasyon</small><b>${cal?`${this._formatFlow(cal.flow_ml_s)} ml/sn`:"Hazır değil"}</b></span><label><span>Dozaj sıvısı</span><select data-dosing-fluid data-address="${channel.address}" data-channel="${channel.id}"><option value="unassigned">Bağlantı atanmadı</option>${fluids.map((fluid)=>`<option value="${fluid.id}" ${(channel.fluid_id||channel.role)===fluid.id?"selected":""}>${fluid.name}${fluid.brand?` · ${fluid.brand}`:""}</option>`).join("")}</select></label></div>`;}).join("");
    const p=this._hardwareDraft?.dosing_policy||{};
    const field=(key,label,unit,min,max,step=1)=>`<label><span>${label}</span><div><input data-dose-policy="${key}" type="number" min="${min}" max="${max}" step="${step}" value="${p[key]??""}"><small>${unit}</small></div></label>`;
    return `<div class="dosing-view"><ha-card class="dosing-policy-card"><div class="dosing-head"><div><span class="eyebrow">Dozaj karar sırası</span><h2>Besin → karıştırma → yeniden ölçüm → pH</h2><p>Besin verildikten sonra çözeltinin karışması beklenir; pH yalnız yeniden ölçümden sonra ve tek yönde düzeltilir.</p></div></div><div class="dosing-policy-grid">${field("nutrient_interval_minutes","Besin dozları arası","dk",30,1440)}${field("mixing_wait_minutes","Karıştırma beklemesi","dk",5,180)}${field("remeasure_wait_minutes","Yeniden ölçüm","dk",1,60)}${field("ph_interval_minutes","pH dozları arası","dk",10,360)}${field("ph_deadband","pH toleransı","pH",.02,1,.01)}${field("max_nutrient_dose_ml","Tek besin dozu üst sınırı","ml",.1,500,.1)}${field("max_ph_dose_ml","Tek pH dozu üst sınırı","ml",.1,50,.1)}</div><div class="policy-rule"><ha-icon icon="mdi:swap-horizontal-bold"></ha-icon><span><b>Tek yönlü pH güvenliği</b><small>Aynı karar çevriminde pH+ ve pH− birlikte çalıştırılmaz.</small></span></div></ha-card><ha-card class="dosing-map-card"><div class="dosing-head"><div><span class="eyebrow">Pompa eşlemesi</span><h2>Dozaj</h2><p>Motor kanallarını besin ve düzenleyici sıvılarla eşleştirin.</p></div></div><div class="dosing-map-list">${rows||'<div class="security-empty">Önce Donanım bölümünden bir motor sürücü ve pompalarını ekleyin.</div>'}</div><div class="card-actions"><span data-hardware-status>${this._hardwareNotice||""}</span><ha-button data-save-dosing appearance="filled">Dozaj ayarlarını kaydet</ha-button></div></ha-card></div>`;
  }
